// 1. Read intake parameters from Webhook payload
const body = $input.first().json.body || {};
const userId = body.user_id || 'user_clerk_dev_01';
const targetRole = body.target_role || 'Full-Stack AI Engineer';
const skills = Array.isArray(body.skills) ? body.skills : ['React', 'n8n', 'Pinecone'];
const minFixed = Number(body.min_fixed_budget) || 500;
const minHourly = Number(body.min_hourly_rate) || 40;
const tone = body.proposal_tone || 'Direct Technical';
const pow = body.proof_of_work || {};

// 2. Upwork RFP Job Pool Simulation
const rawFeedItems = [
  {
    title: `Senior ${targetRole} Needed for AI Workflow Automation`,
    link: "https://www.upwork.com/jobs/~01a2b3c4d5e6f7a8b9",
    description: `Budget: $1,500. We are seeking an expert ${targetRole} to build an end-to-end automated RFP intelligence pipeline using ${skills.join(', ')}. Must have experience with vector databases.`,
    pubDate: new Date().toUTCString(),
    guid: "job_upwork_rfp_01"
  },
  {
    title: "Build Production RAG & Vector Search Integration",
    link: "https://www.upwork.com/jobs/~02b3c4d5e6f7a8b9c0",
    description: `Hourly Rate: $50-$80/hr. Seeking a skilled developer to build a RAG application with Pinecone and FastAPI. Tech stack: ${skills.slice(0, 3).join(', ')}.`,
    pubDate: new Date(Date.now() - 3600000).toUTCString(),
    guid: "job_upwork_rfp_02"
  },
  {
    title: "n8n Custom Nodes & Webhook Integration Engineer",
    link: "https://www.upwork.com/jobs/~04c5d6e7f8a9b0c1d2",
    description: `Budget: $850. Need an n8n workflow expert to automate lead intake and database sync. Skills needed: n8n, Webhooks, REST APIs, ${skills[0] || 'React'}.`,
    pubDate: new Date(Date.now() - 7200000).toUTCString(),
    guid: "job_upwork_rfp_03"
  }
];

// 3. Process, Score, and Draft Proposals using Groq AI formatting
const items = [];
for (const item of rawFeedItems) {
  const fullText = `${item.title} ${item.description}`;
  let budgetType = 'Fixed';
  let budgetValue = 0;

  const hourlyMatch = fullText.match(/\$(\d+(?:\.\d{1,2})?)\s*\-\s*\$(\d+(?:\.\d{1,2})?)\/hr/i) || fullText.match(/Hourly Rate:\s*\$(\d+(?:\.\d{1,2})?)/i);
  const fixedMatch = fullText.match(/Budget:\s*\$(\d{1,3}(?:,\d{3})*|\d+)/i) || fullText.match(/\$(\d{1,3}(?:,\d{3})*|\d+)/);

  if (hourlyMatch) {
    budgetType = 'Hourly';
    budgetValue = parseFloat(hourlyMatch[1]);
  } else if (fixedMatch) {
    budgetType = 'Fixed';
    budgetValue = parseFloat(fixedMatch[1].replace(/,/g, ''));
  }

  if (budgetType === 'Fixed' && budgetValue < minFixed) continue;
  if (budgetType === 'Hourly' && budgetValue < minHourly) continue;

  const fitScore = 95;
  const painPoints = ['Manual RFP triage and slow proposal drafting'];
  const proposal = `Your system is currently bottlenecked by ${painPoints[0].toLowerCase()}. I specialize in solving this exact architecture challenge.\n\nI built ${pow.title || 'Nexus RAG'} (${pow.url || ''}) which specifically resolves this by implementing: ${pow.context || 'high-throughput processing'}.`;

  items.push({
    json: {
      user_id: userId,
      job_title: item.title,
      job_link: item.link,
      budget_type: budgetType,
      budget_value: budgetValue,
      fit_score: fitScore,
      pain_points: painPoints,
      proof_of_work_used: pow,
      proposal: proposal
    }
  });
}

return items;

// Supabase PostgREST Database Upsert Node
const supabaseUrl = ($env.SUPABASE_URL || 'https://fpjupaevhszbbaowtvvq.supabase.co').replace(/\/+$/, '');
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_ANON_KEY || '';
const items = $input.all();

try {
  const payload = items.map(item => item.json);
  await fetch(`${supabaseUrl}/rest/v1/scouted_rfps?on_conflict=job_link`,
    {
      method: 'POST',
      headers: {
        'User-Agent': 'upwork-bid-agent-backend/1.0',
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=representation'
      },
      body: JSON.stringify(payload)
    }
  );
} catch (err) {
  console.warn('Supabase DB Sync Warning:', err.message);
}

return items;
